1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Step = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Customer = {
14	  yearsWithMHPCO: number;
15	};
16	
17	export type Scenario = {
18	  customer: Customer;
19	  steps: Step[];
20	};
21	
22	export type QuoteResult = {
23	  premium: number;
24	};
25	
26	export type ScenarioResult = {
27	  results: QuoteResult[];
28	};
29	
30	const PROCESSING_FEE = 5;
31	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
32	
33	const BASE_PREMIUMS: Record<string, number> = {
34	  sword: 100,
35	  amulet: 60,
36	  staff: 80,
37	  potion: 40,
38	  rune: 25,
39	  moonstone: 25,
40	};
41	
42	const CURSE_SURCHARGE_RATE = 0.5;
43	const HIGH_ENCHANTMENT_THRESHOLD = 5;
44	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
45	const LOYALTY_YEARS_THRESHOLD = 2;
46	const LOYALTY_DISCOUNT_RATE = 0.2;
47	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
48	
49	const BLOCK_SIZE = 3;
50	const BLOCK_BASE_PREMIUM = 60;
51	
52	const basePremiumForType = (type: string): number => BASE_PREMIUMS[type];
53	
54	const itemBasePremium = (item: Item): number => basePremiumForType(item.type);
55	
56	const countByType = (items: Item[]): Map<string, number> => {
57	  const counts = new Map<string, number>();
58	  for (const item of items) {
59	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
60	  }
61	  return counts;
62	};
63	
64	// A block is exactly BLOCK_SIZE alike items, charged as one unit.
65	const formsBlock = (count: number): boolean => count === BLOCK_SIZE;
66	
67	const groupBasePremium = (type: string, count: number): number =>
68	  formsBlock(count) ? BLOCK_BASE_PREMIUM : count * basePremiumForType(type);
69	
70	const policyBasePremium = (items: Item[]): number =>
71	  [...countByType(items)].reduce(
72	    (total, [type, count]) => total + groupBasePremium(type, count),
73	    0,
74	  );
75	
76	// The MHPCO rounds in its own favour: premiums up, payouts down.
77	const roundUpInMHPCOsFavour = (amount: number): number => Math.ceil(amount);
78	
79	// Item-scoped surcharge clauses. Each applies, independently and additively,
80	// to the affected item's own base premium.
81	const ITEM_SURCHARGE_CLAUSES: {
82	  applies: (item: Item) => boolean;
83	  rate: number;
84	}[] = [
85	  {
86	    applies: (item) => item.cursed === true,
87	    rate: CURSE_SURCHARGE_RATE,
88	  },
89	  {
90	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
91	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
92	  },
93	];
94	
95	const itemSurcharge = (item: Item): number => {
96	  const base = itemBasePremium(item);
97	
98	  return ITEM_SURCHARGE_CLAUSES.filter((clause) => clause.applies(item)).reduce(
99	    (total, clause) => total + base * clause.rate,
100	    0,
101	  );
102	};
103	
104	const itemSurcharges = (items: Item[]): number =>
105	  items.reduce((total, item) => total + itemSurcharge(item), 0);
106	
107	// Everything a policy-scoped clause may inspect.
108	type Policy = {
109	  items: Item[];
110	  customer: Customer;
111	  isFollowUpContract: boolean;
112	};
113	
114	// Policy-scoped modifier clauses. Each applies, independently and additively,
115	// to the policy base premium. A negative rate is a discount.
116	const POLICY_MODIFIER_CLAUSES: {
117	  applies: (policy: Policy) => boolean;
118	  rate: number;
119	}[] = [
120	  {
121	    applies: () => true,
122	    rate: FIRST_INSURANCE_SURCHARGE_RATE,
123	  },
124	  {
125	    applies: (policy) =>
126	      policy.customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
127	    rate: -LOYALTY_DISCOUNT_RATE,
128	  },
129	  {
130	    applies: (policy) => policy.isFollowUpContract,
131	    rate: -FOLLOW_UP_CONTRACT_DISCOUNT_RATE,
132	  },
133	];
134	
135	const policyModifiers = (policy: Policy, policyBase: number): number =>
136	  POLICY_MODIFIER_CLAUSES.filter((clause) => clause.applies(policy)).reduce(
137	    (total, clause) => total + policyBase * clause.rate,
138	    0,
139	  );
140	
141	const quote = (policy: Policy): QuoteResult => {
142	  const policyBase = policyBasePremium(policy.items);
143	  const modifiedPremium =
144	    policyBase + itemSurcharges(policy.items) + policyModifiers(policy, policyBase);
145	
146	  return {
147	    premium: roundUpInMHPCOsFavour(modifiedPremium + PROCESSING_FEE),
148	  };
149	};
150	
151	export const runScenario = (scenario: Scenario): ScenarioResult => {
152	  let contractsSoFar = 0;
153	  const results = scenario.steps.map((step) => {
154	    const isFollowUpContract = contractsSoFar > 0;
155	    contractsSoFar += 1;
156	
157	    return quote({
158	      items: step.items,
159	      customer: scenario.customer,
160	      isFollowUpContract,
161	    });
162	  });
163	
164	  return { results };
165	};
