// What a scenario carries from one step to the next.
type ScenarioState = {
  hasIssuedContract: boolean;
};

const INITIAL_SCENARIO_STATE: ScenarioState = {
  hasIssuedContract: false,
};

const runQuoteStep = (
  step: Step,
  customer: Customer,
  state: ScenarioState,
): { result: QuoteResult; state: ScenarioState } => ({
  result: quote({
    items: step.items,
    customer,
    isFollowUpContract: state.hasIssuedContract,
  }),
  state: { hasIssuedContract: true },
});

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const { results } = scenario.steps.reduce<{
    results: QuoteResult[];
    state: ScenarioState;
  }>(
    ({ results, state }, step) => {
      const stepOutcome = runQuoteStep(step, scenario.customer, state);

      return {
        results: [...results, stepOutcome.result],
        state: stepOutcome.state,
      };
    },
    { results: [], state: INITIAL_SCENARIO_STATE },
  );

  return { results };
};

